def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]
    # The three non-background cells at the right are a vertical stamp.
    key = [grid[r][w - 1] for r in range(1, 4)]
    targets = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == 6 and not (c == w - 1 and 1 <= r <= 3)]
    for r, c in targets:
        for dr, color in zip((-1, 0, 1), key):
            if 0 <= r + dr < h:
                out[r + dr][c] = color
    return out
